PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?dir ?dirLabel ?dirBirth ?otherFilm ?otherDir ?otherDirLabel ?otherBirth WHERE {
  VALUES (?film ?otherFilm) {
    (dbr:Airheads_(film) dbr:Return_to_Cabin_by_the_Lake)
    (dbr:Return_to_Cabin_by_the_Lake dbr:Airheads_(film))
  }
  ?film dbo:director ?dir .
  ?otherFilm dbo:director ?otherDir .
  OPTIONAL { ?dir dbo:birthDate ?dirBirth. }
