  OPTIONAL { ?otherDir dbo:birthDate ?otherBirth. }
  OPTIONAL { ?otherDir dbp:birthDate ?otherBirth. }
  OPTIONAL { ?film rdfs:label ?filmLabel. FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?dir rdfs:label ?dirLabel. FILTER(lang(?dirLabel) = "en") }
  OPTIONAL { ?otherDir rdfs:label ?otherDirLabel. FILTER(lang(?otherDirLabel) = "en") }
  FILTER(bound(?dirBirth) && bound(?otherBirth) && ?dirBirth < ?otherBirth)
}
LIMIT 10

